    private static List<Entry> cache;

    public static synchronized List<Entry> all() {
        if (cache == null) {
            List<Entry> list = new ArrayList<Entry>();
            for (String row : DATA) {
                String[] p = row.split(";");
                String proto = p[2];
                int g = -1;
                int[] raw = null;
                if (p.length > 7) {
                    if ("RAW".equals(proto)) {
                        String[] parts = p[7].split(",");
                        raw = new int[parts.length];
                        for (int i = 0; i < parts.length; i++) raw[i] = Integer.parseInt(parts[i]);
                    } else if ("KASE".equals(proto)) {
                        raw = new int[6];
                        for (int i = 0; i < 6; i++) {
                            raw[i] = Integer.parseInt(p[7].substring(2 * i, 2 * i + 2), 16);
                        }
                    } else {
                        g = Integer.parseInt(p[7]);
                    }
                }
                list.add(new Entry(
                        p[0].split("/"),
                        p[1],
                        "D".equals(p[6]),
                        proto,
                        Integer.parseInt(p[3]),
                        Integer.parseInt(p[4]),
                        Integer.parseInt(p[5]),
                        g,
                        raw));
            }
            cache = Collections.unmodifiableList(list);
        }
        return cache;
    }

    /** Todas las marcas disponibles, ordenadas sin distinguir mayúsculas. */
    public static List<String> brands() {
        List<String> out = new ArrayList<String>();
        for (Entry e : all()) {
            for (String b : e.brands) {
                if (!out.contains(b)) out.add(b);
            }
        }
        Collections.sort(out, String.CASE_INSENSITIVE_ORDER);
        return out;
    }

    /**
     * Códigos para enviar, primero los que alternan y al final los "mute ON" discretos,
     * así un equipo que tenga ambos termina siempre silenciado.
     */
    public static List<Entry> select(boolean tv, boolean audio, boolean car, boolean other,
                                     String brand) {
        List<Entry> toggles = new ArrayList<Entry>();
        List<Entry> discretes = new ArrayList<Entry>();
        for (Entry e : all()) {
            if (brand != null) {
                boolean match = false;
                for (String b : e.brands) {
                    if (b.equals(brand)) { match = true; break; }
                }
                if (!match) continue;
            }
            boolean typeOk = (tv && e.tv) || (audio && e.audio) || (car && e.car)
                    || (other && e.other);
            if (!typeOk) continue;
            if (e.discrete) discretes.add(e); else toggles.add(e);
        }
        toggles.addAll(discretes);
        return toggles;
    }
